// Original reference for: Encode and Decode Strings
class Solution { public: string encode(vector<string>& words){ string out; for(auto&s:words) out+=to_string(s.size())+'#'+s; return out; } vector<string> decode(string data){ vector<string> out; for(int i=0;i<(int)data.size();){ int j=i; while(data[j]!='#') ++j; int n=stoi(data.substr(i,j-i)); out.push_back(data.substr(j+1,n)); i=j+1+n; } return out; } };

