// Original reference for: Network Delay Time
class Solution { public: vector<int> solve(int n,vector<vector<pair<int,int>>>& g,int src){const int INF=1e9;vector<int>d(n,INF);priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>>pq;d[src]=0;pq.push({0,src});while(!pq.empty()){auto [du,u]=pq.top();pq.pop();if(du!=d[u])continue;for(auto [v,w]:g[u])if(du+w<d[v]){d[v]=du+w;pq.push({d[v],v});}}return d;} };

